.kairo-story-track {
  position: relative;
  width: 100%;
  height: 580vh;
  background-color: var(--black-carbon);
}

@media (max-width: 1024px) {
  .kairo-story-track {
    height: 480vh;
  }
}

@media (max-width: 640px) {
  .kairo-story-track {
    height: 410vh;
  }
}

.kairo-story-sticky {
  position: sticky;
  top: 0;
  width: 100%;
  height: 100svh;
  min-height: 560px;
  overflow: hidden;
  background-color: var(--black-carbon);
}

/* Shared 16:9 cover coordinate box for city hotspots so markers stay locked to subject features on any aspect ratio */
.kairo-cover-stage {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: max(100vw, 177.78svh);
  height: max(100svh, 56.25vw);
  pointer-events: none;
}

/* Optical copper ring specular sweep on load */
@keyframes kairoLensGlint {
  0% {
    opacity: 0;
    transform: rotate(-35deg) scale(0.98);
  }
  35% {
    opacity: 0.55;
  }
  100% {
    opacity: 0;
    transform: rotate(25deg) scale(1.01);
  }
}

.kairo-lens-glint {
  animation: kairoLensGlint 2.6s cubic-bezier(0.16, 1, 0.3, 1) 0.25s 1 forwards;
}

/* Viewfinder reticle corner brackets */
.kairo-reticle-corner {
  position: absolute;
  width: 14px;
  height: 14px;
  border-color: rgba(230, 143, 99, 0.65);
  pointer-events: none;
}

:root {
  --black-carbon: #121315;
  --graphite: #1d2024;
  --titanium: #7f858d;
  --porcelain: #f2efe9;
  --copper: #e68f63;
  --copper-soft: #b8785d;
  --stone: #d2cec7;
  --body-muted: #a8aaa9;
  --panel-line: rgba(242, 239, 233, 0.15);
  --panel-line-dark: rgba(18, 19, 21, 0.12);

  --font-display: 'Bricolage Grotesque', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, SFMono-Regular, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  background-color: var(--black-carbon);
  color: var(--porcelain);
  font-family: var(--font-sans);
  scroll-behavior: smooth;
  overflow-x: clip;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--black-carbon);
  color: var(--porcelain);
  font-family: var(--font-sans);
  overflow-x: clip;
  min-height: 100%;
  text-rendering: optimizeLegibility;
}

.font-display-kairo {
  font-family: var(--font-display);
}

.font-sans-kairo {
  font-family: var(--font-sans);
}

.font-mono-kairo {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

/* Intentional keyboard focus ring */
:focus-visible {
  outline: 2px solid var(--copper);
  outline-offset: 3px;
}

/* Button edge copper line response */
.kairo-btn-primary {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.625rem;
  padding: 0.75rem 1.375rem;
  background-color: var(--porcelain);
  color: var(--black-carbon);
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  border: 1px solid rgba(242, 239, 233, 0.9);
  border-radius: 2px;
  transition:
    background-color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    border-color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  white-space: nowrap;
}

.kairo-btn-primary:hover {
  background-color: var(--copper);
  border-color: var(--copper);
  color: var(--black-carbon);
}

.kairo-btn-secondary {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.625rem;
  padding: 0.75rem 1.375rem;
  background-color: rgba(18, 19, 21, 0.55);
  color: var(--porcelain);
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  border: 1px solid rgba(242, 239, 233, 0.24);
  border-radius: 2px;
  backdrop-filter: blur(8px);
  transition:
    border-color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    background-color 180ms cubic-bezier(0.16, 1, 0.3, 1),
    color 180ms cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  white-space: nowrap;
}

.kairo-btn-secondary:hover {
  border-color: var(--copper);
  background-color: rgba(230, 143, 99, 0.12);
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Optical handoff mask and editorial chapter surfaces */
.kairo-porcelain-chapter {
  background-color: var(--porcelain);
  color: var(--black-carbon);
}

.kairo-stone-chapter {
  background-color: var(--stone);
  color: var(--black-carbon);
}

.kairo-carbon-chapter {
  background-color: var(--black-carbon);
  color: var(--porcelain);
}

.kairo-hairline-top {
  border-top: 1px solid var(--panel-line);
}

.kairo-hairline-dark-top {
  border-top: 1px solid var(--panel-line-dark);
}

/* Smooth image pan for exploded camera and collection trio */
.kairo-pan-surface {
  transition:
    transform 520ms cubic-bezier(0.16, 1, 0.3, 1),
    object-position 520ms cubic-bezier(0.16, 1, 0.3, 1),
    filter 320ms cubic-bezier(0.16, 1, 0.3, 1);
}

